input.command:
mkdir -p src && cat > Cargo.toml <<'EOF'
[package]
name = "word-frequency"
version = "0.1.0"
edition = "2021"

[dependencies]
EOF
cat > src/main.rs <<'EOF'
use std::collections::HashMap;
use std::io::{self, BufWriter, Write};
use std::process::ExitCode;

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1) else {
        eprintln!("usage: word-frequency <file>");
        return ExitCode::FAILURE;
    };
    let data = match std::fs::read(&path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error reading {}: {e}", path.to_string_lossy());
            return ExitCode::FAILURE;
        }
    };

    let mut counts: HashMap<Vec<u8>, u64> = HashMap::new();
    for word in data.split(|b| !b.is_ascii_alphanumeric()) {
        if word.is_empty() {
            continue;
        }
        let lower = word.to_ascii_lowercase();
        *counts.entry(lower).or_insert(0) += 1;
    }

    let mut entries: Vec<(Vec<u8>, u64)> = counts.into_iter().collect();
    entries.sort_unstable_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    for (word, count) in entries.iter().take(10) {
        // Words are pure ASCII, so writing raw bytes is valid UTF-8.
        let _ = out.write_all(word);
        let _ = writeln!(out, " {count}");
    }
    let _ = out.flush();
    ExitCode::SUCCESS
}
EOF
cargo build --release 2>&1 | tail -2 && cargo clippy --release -- -D warnings 2>&1 | tail -2
printf 'The the THE a b2 B2 café x_y z\n\xff zz' > /tmp/wf1.txt; ./target/release/word-frequency /tmp/wf1.txt; echo "rc=$?"
: > /tmp/wf2.txt; ./target/release/word-frequency /tmp/wf2.txt; echo "rc=$?"
seq 1 30 | awk '{for(i=0;i<$1%5;i++) print "w"$1}' > /tmp/wf3.txt; ./target/release/word-frequency /tmp/wf3.txt | wc -l

